#!/usr/bin/env python3
"""Remove executable JavaScript from HTML while preserving safe source formatting."""
import html
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote

VOID = frozenset('area base br col embed hr img input link meta param source track wbr'.split())
DROP = frozenset({'script', 'applet', 'object', 'embed'})
URL_ATTRS = frozenset('href src action formaction xlink:href data poster background cite manifest codebase archive longdesc usemap profile'.split())
BAD_CSS = re.compile(r'expression\s*\(|behavior\s*:|-moz-binding\s*:|@import\b|url\s*\(\s*[\"\']?\s*(?:javascript|vbscript|data\s*:\s*text/html)\s*:', re.I)
TOKEN = re.compile(r'<!--.*?-->|<![^>]*>|<\?[^>]*>|</?[A-Za-z][^>]*>', re.S)
ATTR = re.compile(r'''([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?''')
RAW = frozenset({'textarea', 'title', 'style', 'xmp', 'noembed', 'noframes', 'plaintext'})


def unsafe_url(value):
    value = html.unescape(value)
    for _ in range(3):
        decoded = unquote(value)
        if decoded == value:
            break
        value = decoded
    value = re.sub(r'[\x00-\x20\x7f]+', '', value).casefold()
    if value.startswith(('javascript:', 'vbscript:')):
        return True
    return value.startswith('data:') and not value.startswith(('data:image/', 'data:audio/', 'data:video/', 'data:font/'))


def parse_tag(raw):
    m = re.match(r'<(/?)\s*([^\s/>]+)', raw)
    if not m:
        return None
    close, name = m.groups()
    attr_text = raw[m.end():]
    # Remove closing delimiter without consuming quoted '>' characters.
    attr_text = re.sub(r'/?>\s*$', '', attr_text)
    attrs = []
    for a in ATTR.finditer(attr_text):
        name, double, single, bare = a.groups()
        value = double if double is not None else single if single is not None else bare
        attrs.append((name, value))
    return close, name.lower(), attrs


def sanitize_tag(raw):
    parsed = parse_tag(raw)
    if not parsed or raw.startswith(('<!--', '<!', '<?')):
        return raw
    close, tag, attrs = parsed
    if close:
        return raw
    safe = []
    changed = False
    for name, value in attrs:
        key = name.lower()
        if key.startswith('on') or key == 'srcdoc':
            changed = True
            continue
        if value is not None and key in URL_ATTRS and unsafe_url(value):
            changed = True
            continue
        if value is not None and key == 'style':
            cleaned = BAD_CSS.sub('', value)
            if cleaned != value:
                changed = True
                value = cleaned
        safe.append((name, value))
    if not changed:
        return raw
    self_closing = raw.rstrip().endswith('/>')
    result = ['<' + tag]
    for name, value in safe:
        result.append(' ' + name if value is None else ' ' + name + '="' + html.escape(value, quote=True) + '"')
    result.append('/>' if self_closing else '>')
    return ''.join(result)


def sanitize(source):
    out = []
    cursor = 0
    suppressed = []
    raw_text = None
    for match in TOKEN.finditer(source):
        token = match.group()
        parsed = parse_tag(token)
        if raw_text:
            if not parsed or not parsed[0] or parsed[1] != raw_text:
                continue
            if not suppressed:
                out.append(source[cursor:match.end()])
            cursor = match.end()
            raw_text = None
            continue
        if not suppressed:
            out.append(source[cursor:match.start()])
        cursor = match.end()
        if not parsed:
            if not suppressed:
                out.append(token)
            continue
        closing, tag, _ = parsed
        if suppressed:
            if closing and tag == suppressed[-1]:
                suppressed.pop()
            elif not closing and tag in DROP and tag not in VOID and not token.rstrip().endswith('/>'):
                suppressed.append(tag)
            continue
        if not closing and tag in DROP:
            if tag not in VOID and not token.rstrip().endswith('/>'):
                suppressed.append(tag)
            continue
        # Sanitize srcdoc recursively instead of discarding safe embedded HTML.
        if not closing and re.search(r'\bsrcdoc\s*=', token, re.I):
            token = re.sub(r'(?i)\s+srcdoc\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)', lambda m: ' srcdoc="' + html.escape(sanitize(html.unescape(m.group(1)[1:-1] if m.group(1)[0] in '\"\'' else m.group(1))), quote=True) + '"', token)
        out.append(sanitize_tag(token))
        if not closing and tag in RAW and tag not in VOID:
            raw_text = tag
    if not suppressed:
        out.append(source[cursor:])
    return ''.join(out)


def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py HTML_FILE', file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    with path.open(encoding='utf-8', errors='surrogateescape', newline='') as f:
        source = f.read()
    with path.open('w', encoding='utf-8', errors='surrogateescape', newline='') as f:
        f.write(sanitize(source))
    return 0

if __name__ == '__main__':
    sys.exit(main())
